1|// CLI: npm run build:book -- oz [--step ingest|segment|classify|resplit|cluster] [--force]
2|import { readFileSync } from "node:fs";
3|import { join } from "node:path";
4|import { runClassify } from "./classify";
5|import { runCluster } from "./cluster-tracks";
6|import { bookConfig, runIngest } from "./ingest";
7|import type { StepCtx } from "./ingest";
8|import { createJevClient } from "./jev";
9|import { createMetaClient } from "./meta";
10|import { runResplit } from "./resplit";
11|import { runSegment } from "./segment";
12|
13|const STEPS = ["ingest", "segment", "classify", "resplit", "cluster"] as const;
14|
15|function loadEnv(): void {
16|  try {
17|    if (typeof process.loadEnvFile === "function") process.loadEnvFile(".env.local");
18|  } catch {
19|    // No .env.local is fine; env may come from elsewhere.
20|  }
21|}
22|
23|function env(name: string, fallback?: string): string {
24|  const value = process.env[name] ?? fallback;
25|  if (value === undefined || value === "") throw new Error(`${name} is not set`);
26|  return value;
27|}
28|
29|async function main(): Promise<void> {
30|  loadEnv();
31|  const args = process.argv.slice(2);
32|  const bookKey = args.find((a) => !a.startsWith("--")) ?? "";
33|  const stepFlag = args.indexOf("--step");
34|  const stepArg = stepFlag === -1 ? undefined : args[stepFlag + 1];
35|  const force = args.includes("--force");
36|  if (!bookKey) throw new Error("usage: build:book <book> [--step ingest|segment|classify|resplit|cluster] [--force]");
37|  bookConfig(bookKey); // fails fast on unknown keys with the valid list
38|  const only = stepArg ?? "";
39|  if (only !== "" && !(STEPS as readonly string[]).includes(only)) {
40|    throw new Error(`unknown step "${only}", valid steps: ${STEPS.join(", ")}`);
41|  }
42|  const ctx: StepCtx = { bookKey, force, dir: join("data", "books", bookKey) };
43|  const run: Record<(typeof STEPS)[number], boolean> = {
44|    ingest: only === "" || only === "ingest",
45|    segment: only === "" || only === "segment",
46|    classify: only === "" || only === "classify",
47|    resplit: only === "" || only === "resplit",
48|    cluster: only === "" || only === "cluster",
49|  };
50|  if (run.ingest) {
51|    const book = await runIngest(ctx);
52|    console.log(`ingest: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${book.textVersion}`);
53|  }
54|  if (run.segment) {
55|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
56|    console.log(`segment: ${meta.model}`);
57|    const scenes = await runSegment(ctx, { meta });
58|    console.log(`segment: ${scenes.length} scenes`);
59|  }
60|  if (run.classify) {
61|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
62|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
63|    const scenes = await runClassify(ctx, { jev, meta });
64|    const overrides = scenes.filter((s) => s.muse_override !== null).length;
65|    const failures = scenes.filter((s) => s.final === null).length;
66|    console.log(`classify: ${scenes.length} scenes, ${overrides} overrides, ${failures} failures`);
67|  }
68|  if (run.resplit) {
69|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
70|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
71|    const scenes = await runResplit(ctx, { jev, meta });
72|    console.log(`resplit: ${scenes.length} scenes`);
73|  }
74|  if (run.cluster) {
75|    await runCluster(ctx);
76|    console.log("cluster: wrote music-clusters.json");
77|  }
78|  printSummary(ctx.dir);
79|}
80|
81|function printSummary(dir: string): void {
82|  const book = JSON.parse(readFileSync(join(dir, "book.json"), "utf8")) as {
83|    chapters: unknown[];
84|    paragraphs: unknown[];
85|  };
86|  let scenes: { final: { vector: Record<string, number> } | null }[] = [];
87|  let overrideRate = 0;
88|  let jev = { cost_usd: 0 };
89|  let meta = { cost_usd: 0 };
90|  let total = 0;
91|  try {
92|    const analysis = JSON.parse(readFileSync(join(dir, "analysis.json"), "utf8")) as {
93|      scenes: (typeof scenes)[number][];
94|      override_rate: number;
95|      provenance: { jev: typeof jev; meta: typeof meta; total_cost_usd: number };
96|    };
97|    scenes = analysis.scenes;
98|    overrideRate = analysis.override_rate;
99|    jev = analysis.provenance.jev;
100|    meta = analysis.provenance.meta;
101|    total = analysis.provenance.total_cost_usd;
102|  } catch {
103|    // Steps after ingest may not have run yet.
104|  }
105|  const dist = new Map<string, number>();
106|  let failures = 0;
107|  for (const scene of scenes) {
108|    if (!scene.final) {
109|      failures += 1;
110|      continue;
111|    }
112|    const top = Object.entries(scene.final.vector).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "?";
113|    dist.set(top, (dist.get(top) ?? 0) + 1);
114|  }
115|  console.log(`summary: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${scenes.length} scenes`);
116|  console.log(`emotions: ${[...dist.entries()].map(([id, count]) => `${id} ${count}`).join(", ") || "none yet"}`);
117|  console.log(`override rate ${((overrideRate ?? 0) * 100).toFixed(1)}%, failures ${failures}`);
118|  console.log(`cost: jev $${(jev.cost_usd ?? 0).toFixed(4)}, meta $${(meta.cost_usd ?? 0).toFixed(4)}, total $${(total ?? 0).toFixed(4)}`);
119|}
120|
121|main().catch((error: unknown) => {
122|  console.error(`error: ${(error as Error).message}`);
123|  process.exit(1);
124|});

