5|export function readIfFresh<T extends { textVersion: string }>(path: string, textVersion: string): T | null {
6|  let raw: string;
7|  try {
8|    raw = readFileSync(path, "utf8");
9|  } catch {
10|    return null;
11|  }
12|  try {
13|    const parsed = JSON.parse(raw) as T;
14|    return parsed.textVersion === textVersion ? parsed : null;
15|  } catch {
16|    return null;
17|  }
