Read text file `pipeline/classify.ts`.
1|// Step 3: one Jev call per scene, Meta override on low confidence.
2|// Hard failures record the error and continue; they never invent a vector.
3|import { readFileSync, writeFileSync } from "node:fs";
4|import { join } from "node:path";
5|import { EMOTIONS } from "../core/types";
6|import type { AnalyzedScene, Book, EmotionId, Scene, SceneEmotion } from "../core/types";
7|import { jevFinal, needsOverride, renormalize8 } from "../core/emotion";
8|import { readIfFresh } from "./cache";
9|import type { StepCtx } from "./ingest";
10|import { runPool } from "./http";
11|import type { JevClient } from "./jev";
12|import type { MetaClient } from "./meta";
13|import { jevCostUsd, metaCostUsd } from "./prices";
14|
15|const OVERRIDE_SCHEMA = {
16|  type: "object",
17|  properties: {
18|    vector: {
19|      type: "object",
20|      properties: Object.fromEntries(EMOTIONS.map((id) => [id, { type: "number" }])),
21|      required: [...EMOTIONS],
22|      additionalProperties: false,
23|    },
24|    reason: { type: "string" },
25|  },
26|  required: ["vector", "reason"],
27|  additionalProperties: false,
28|};
29|
30|export interface ClassifyMetaUsage {
31|  model: string;
32|  requests: number;
33|  promptTokens: number;
34|  cachedTokens: number;
35|  completionTokens: number;
36|  costUsd: number;
37|}
38|
39|export async function classifyScene(
40|  scene: Scene,
41|  text: string,
42|  bookTitle: string,
43|  chapterTitle: string,
44|  deps: { jev: JevClient; meta: MetaClient },
45|  metaUsage: ClassifyMetaUsage,
46|): Promise<SceneEmotion> {
47|  let jev;
48|  try {
49|    jev = await deps.jev.classify({ book: bookTitle, chapter: chapterTitle, sceneTitle: scene.title, scene: text });
50|  } catch (error) {
51|    return { jev: null, muse_override: null, final: null, error: `jev failed: ${(error as Error).message}` };
52|  }
53|  if (!needsOverride({ choice: jev.choice, confidence: jev.confidence, probabilities: jev.vector })) {
54|    const final = jevFinal({ probabilities: jev.vector, intensity: jev.intensity, tempo: jev.tempo });
55|    return { jev, muse_override: null, final, error: final === null ? "jev vector renormalizes to zero" : null };
56|  }
57|  try {
58|    const result = await deps.meta.completeJson({
59|      system: "You score soundtrack mood as a probability mix over 8 feelings. Answer with JSON only.",
60|      user:
61|        `Scene "${scene.title}": ${text}\nJev vector: ${JSON.stringify(jev.vector)} ` +
62|        `(choice ${jev.choice}, confidence ${jev.confidence}). ` +
63|        `Give a probability mix over the 8 feelings only, plus one short sentence for reason.`,
64|      schemaName: "emotion_override",
65|      schema: OVERRIDE_SCHEMA,
66|    });
67|    metaUsage.requests += 1;
68|    metaUsage.promptTokens += result.promptTokens;
69|    metaUsage.cachedTokens += result.cachedTokens;
70|    metaUsage.completionTokens += result.completionTokens;
71|    const parsed = result.data as { vector?: Partial<Record<EmotionId, number>>; reason?: unknown };
72|    const vector = renormalize8(parsed.vector ?? {});
73|    if (vector === null) {
74|      return { jev, muse_override: null, final: null, error: "override vector is all zero" };
75|    }
76|    const override = { vector, reason: String(parsed.reason ?? ""), model: deps.meta.model };
77|    return { jev, muse_override: override, final: { vector, intensity: jev.intensity, tempo: jev.tempo }, error: null };
78|  } catch (error) {
79|    return { jev, muse_override: null, final: null, error: `override failed: ${(error as Error).message}` };
80|  }
81|}
82|
83|export async function runClassify(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
84|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
85|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
86|    scenes: Scene[];
87|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
88|  };
89|  const outPath = join(ctx.dir, "analysis.json");
90|  if (!ctx.force) {
91|    const fresh = readIfFresh<{ textVersion: string; scenes: AnalyzedScene[] }>(outPath, book.textVersion);
92|    if (fresh) return fresh.scenes;
93|  }
94|  const metaUsage: ClassifyMetaUsage = { model: deps.meta.model, requests: 0, promptTokens: 0, cachedTokens: 0, completionTokens: 0, costUsd: 0 };
95|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
96|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
97|  let resplit: unknown;
98|  try {
99|    const prev = JSON.parse(readFileSync(outPath, "utf8")) as { provenance?: { resplit?: unknown } };
100|    resplit = prev.provenance?.resplit;
101|  } catch {
102|    resplit = undefined; // no previous analysis yet
103|  }
104|  let jevInputTokens = 0;
105|  let jevOutputTokens = 0;
106|  let jevRequests = 0;
107|  const scenes = await runPool(scenesFile.scenes, 4, async (scene) => {
108|    const texts: string[] = [];
109|    for (let n = scene.start_n; n <= scene.end_n; n++) texts.push(byN.get(n)?.text ?? "");
110|    const emotion = await classifyScene(scene, texts.join("\n"), book.title, chapterTitle.get(scene.ch) ?? "", deps, metaUsage);
111|    if (emotion.jev) {
112|      jevInputTokens += emotion.jev.input_tokens;
113|      jevOutputTokens += emotion.jev.output_tokens;
114|      jevRequests += 1;
115|    }
116|    return { ...scene, ...emotion };
117|  });
118|  metaUsage.costUsd = metaCostUsd({ prompt: metaUsage.promptTokens, cached: metaUsage.cachedTokens, completion: metaUsage.completionTokens });
119|  const jevCost = jevCostUsd(jevInputTokens);
120|  const segment = scenesFile.provenance.meta;
121|  const metaTotal = {
122|    model: deps.meta.model,
123|    requests: segment.requests + metaUsage.requests,
124|    prompt_tokens: segment.prompt_tokens + metaUsage.promptTokens,
125|    cached_tokens: segment.cached_tokens + metaUsage.cachedTokens,
126|    completion_tokens: segment.completion_tokens + metaUsage.completionTokens,
127|    cost_usd: segment.cost_usd + metaUsage.costUsd,
128|  };
129|  const seen = new Set(scenes.map((s) => s.id));
130|  if (seen.size !== scenes.length) throw new Error("classify found duplicate scene ids");
131|  const overrides = scenes.filter((s) => s.muse_override !== null).length;
132|  writeFileSync(
133|    outPath,
134|    `${JSON.stringify({
135|      bookId: book.id,
136|      textVersion: book.textVersion,
137|      scenes,
138|      override_rate: scenes.length > 0 ? overrides / scenes.length : 0,
139|      provenance: {
140|        date: new Date().toISOString(),
141|        jev: { model: deps.jev.model, requests: jevRequests, input_tokens: jevInputTokens, output_tokens: jevOutputTokens, cost_usd: jevCost },
142|        meta: metaTotal,
143|        total_cost_usd: jevCost + metaTotal.cost_usd,
144|        ...(resplit !== undefined ? { resplit } : {}),
145|      },
146|    })}\n`,
147|  );
148|  return scenes;
149|}

Read text file `pipeline/resplit.ts`.
1|// Step: re-split scenes where the dominant emotion changes strongly
2|// along the text. Reads book.json and analysis.json, rewrites
3|// scenes.json and analysis.json. Skips when provenance.resplit exists.
4|// A Muse resplit failure keeps the scene whole and lands in muse_failures.
5|import { readFileSync, writeFileSync } from "node:fs";
6|import { join } from "node:path";
7|import { renormalize8 } from "../core/emotion";
8|import { countWords } from "../core/reader";
9|import {
10|  RESPLIT_ASK_MARGIN,
11|  RESPLIT_AUTO_MARGIN,
12|  buildWindows,
13|  isResplitCandidate,
14|  meanVector,
15|  planSplits,
16|  splitIds,
17|  topOf,
18|} from "../core/resplit";
19|import type { ResplitWindow, SplitCall } from "../core/resplit";
20|import { validateBookCoverage } from "../core/scenes";
21|import type { AnalyzedScene, Book, EmotionId, Scene, SceneEmotion } from "../core/types";
22|import { classifyScene } from "./classify";
23|import type { ClassifyMetaUsage } from "./classify";
24|import type { StepCtx } from "./ingest";
25|import { runPool } from "./http";
26|import type { JevClient } from "./jev";
27|import type { MetaClient } from "./meta";
28|import { jevCostUsd, metaCostUsd } from "./prices";
29|
30|const DECISION_SCHEMA = {
31|  type: "object",
32|  properties: { split: { type: "boolean" }, reason: { type: "string" } },
33|  required: ["split", "reason"],
34|  additionalProperties: false,
35|};
36|
37|const TITLES_SCHEMA = {
38|  type: "object",
39|  properties: {
40|    parts: {
41|      type: "array",
42|      items: {
43|        type: "object",
44|        properties: {
45|          start_n: { type: "number" },
46|          end_n: { type: "number" },
47|          title: { type: "string" },
48|          summary: { type: "string" },
49|          characters: { type: "array", items: { type: "string" } },
50|        },
51|        required: ["start_n", "end_n", "title", "summary", "characters"],
52|        additionalProperties: false,
53|      },
54|    },
55|  },
56|  required: ["parts"],
57|  additionalProperties: false,
58|};
59|
60|export interface ResplitEntry {
61|  from: string;
62|  at_n: number;
63|  margin: number;
64|  window_left: EmotionId;
65|  window_right: EmotionId;
66|  final_left: EmotionId | null;
67|  final_right: EmotionId | null;
68|  decided_by: "rule" | "muse";
69|  reason?: string;
70|}
71|
72|export interface ResplitRejected {
73|  from: string;
74|  at_n: number;
75|  margin: number;
76|  window_left: EmotionId;
77|  window_right: EmotionId;
78|  reason: string;
79|}
80|
81|export interface ResplitMergedBack {
82|  from: string;
83|  top: EmotionId | null;
84|}
85|
86|interface Usage {
87|  jevRequests: number;
88|  jevInputTokens: number;
89|  jevOutputTokens: number;
90|  meta: ClassifyMetaUsage;
91|}
92|
93|function newUsage(model: string): Usage {
94|  return { jevRequests: 0, jevInputTokens: 0, jevOutputTokens: 0, meta: { model, requests: 0, promptTokens: 0, cachedTokens: 0, completionTokens: 0, costUsd: 0 } };
95|}
96|
97|function museFailureReason(err: unknown): string {
98|  const msg = err instanceof Error ? err.message : String(err);
99|  return msg.slice(0, 200);
100|}
101|
102|function trackMeta(usage: Usage, result: { promptTokens: number; cachedTokens: number; completionTokens: number }): void {
103|  usage.meta.requests += 1;
104|  usage.meta.promptTokens += result.promptTokens;
105|  usage.meta.cachedTokens += result.cachedTokens;
106|  usage.meta.completionTokens += result.completionTokens;
107|}
108|
109|export async function runResplit(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
110|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
111|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
112|    bookId: string;
113|    textVersion: string;
114|    scenes: Scene[];
115|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
116|  };
117|  const analysisFile = JSON.parse(readFileSync(join(ctx.dir, "analysis.json"), "utf8")) as {
118|    bookId: string;
119|    textVersion: string;
120|    scenes: AnalyzedScene[];
121|    provenance: {
122|      date: string;
123|      jev: { model: string; requests: number; input_tokens: number; output_tokens: number; cost_usd: number };
124|      meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number };
125|      total_cost_usd: number;
126|      resplit?: unknown;
127|    };
128|  };
129|  if (!ctx.force && analysisFile.textVersion === book.textVersion && analysisFile.provenance.resplit) {
130|    return analysisFile.scenes;
131|  }
132|  const usage = newUsage(deps.meta.model);
133|  const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
134|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
135|  const wordsOf = (scene: { start_n: number; end_n: number }): number => {
136|    let words = 0;
137|    for (let n = scene.start_n; n <= scene.end_n; n++) words += countWords(byN.get(n) ?? "");
138|    return words;
139|  };
140|  const candidates = analysisFile.scenes.filter((s) => isResplitCandidate(wordsOf(s), s.final));
141|  let windowsClassified = 0;
142|  const windowFailures: string[] = [];
143|  const museFailures: { from: string; reason: string }[] = [];
144|  const rejected: ResplitRejected[] = [];
145|  const mergedBack: ResplitMergedBack[] = [];
146|
147|  const splitScenes = await runPool(candidates, 4, async (scene) => {
148|    const paragraphs = book.paragraphs.filter((p) => p.n >= scene.start_n && p.n <= scene.end_n);
149|    const spans = buildWindows(paragraphs);
150|    const windows: ResplitWindow[] = [];
151|    for (const span of spans) {
152|      const text = paragraphs.filter((p) => p.n >= span.startN && p.n <= span.endN).map((p) => p.text).join("\n");
153|      let result;
154|      try {
155|        result = await deps.jev.classify({ book: book.title, chapter: chapterTitle.get(scene.ch) ?? "", sceneTitle: scene.title, scene: text });
156|      } catch {
157|        windowFailures.push(scene.id);
158|        return null;
159|      }
160|      usage.jevRequests += 1;
161|      usage.jevInputTokens += result.input_tokens;
162|      usage.jevOutputTokens += result.output_tokens;
163|      const { unknown: _dropped, ...rest } = result.vector;
164|      const vector = renormalize8(rest);
165|      if (vector === null) {
166|        windowFailures.push(scene.id);
167|        return null;
168|      }
169|      windows.push({ ...span, vector });
170|      windowsClassified += 1;
171|    }
172|    if (windows.length < 2) return null;
173|    const taken: { call: SplitCall; by: "rule" | "muse" }[] = [];
174|    const reasons = new Map<number, string>();
175|    let cuts: number[];
176|    try {
177|      cuts = await planSplits(
178|        windows,
179|        async (call) => {
180|          const boundaryN = windows[call.index]?.startN ?? 0;
181|          const before = paragraphs.filter((p) => p.n < boundaryN).slice(-2);
182|          const after = paragraphs.filter((p) => p.n >= boundaryN).slice(0, 2);
183|          const left = meanVector(windows.slice(0, call.index));
184|          const right = meanVector(windows.slice(call.index));
185|          const result = await deps.meta.completeJson({
186|            system: "You judge whether a scene needs two music tracks. Answer with JSON only.",
187|            user:
188|              `Scene "${scene.title}" may change mood at paragraph ${windows[call.index]?.startN}. ` +
189|              `Left mood ${call.left} ${JSON.stringify(left)}, right mood ${call.right} ${JSON.stringify(right)}. ` +
190|              `Split only when the dominant feeling changes strongly and stays changed, not for a mixed blend. ` +
191|              `Before: ${before.map((p) => `[${p.n}] ${p.text}`).join("\n")}\nAfter: ${after.map((p) => `[${p.n}] ${p.text}`).join("\n")}`,
192|            schemaName: "resplit_decision",
193|            schema: DECISION_SCHEMA,
194|          });
195|          trackMeta(usage, result);
196|          const data = result.data as { split?: unknown; reason?: unknown };
197|          const split = data.split === true;
198|          const reason = String(data.reason ?? "");
199|          if (split) reasons.set(call.index, reason);
200|          else rejected.push({ from: scene.id, at_n: boundaryN, margin: call.margin, window_left: call.left, window_right: call.right, reason });
201|          return split;
202|        },
203|        (call, by) => taken.push({ call, by }),
204|      );
205|    } catch (err) {
206|      museFailures.push({ from: scene.id, reason: museFailureReason(err) });
207|      return null;
208|    }
209|    if (cuts.length === 0) return null;
