227|      }
228|    } catch (err) {
229|      museFailures.push({ from: scene.id, reason: museFailureReason(err) });
230|      return null;
231|    }
232|    const bases = parts.map((part) => ({
233|      ch: scene.ch,
234|      start_n: part.start_n,
235|      end_n: part.end_n,
