253|    const groups: number[][] = [];
254|    for (let i = 0; i < bases.length; i++) {
255|      const last = groups[groups.length - 1];
256|      const prev = last ? tops[last[last.length - 1] ?? -1] : undefined;
257|      const top = tops[i];
258|      if (last && top !== null && top === prev) last.push(i);
