355|          model: segmentMeta.model,
356|          requests: segmentMeta.requests + usage.meta.requests,
357|          prompt_tokens: segmentMeta.prompt_tokens + usage.meta.promptTokens,
358|          cached_tokens: segmentMeta.cached_tokens + usage.meta.cachedTokens,
359|          completion_tokens: segmentMeta.completion_tokens + usage.meta.completionTokens,
