367|    model: prevMeta.model,
368|    requests: prevMeta.requests + usage.meta.requests,
369|    prompt_tokens: prevMeta.prompt_tokens + usage.meta.promptTokens,
370|    cached_tokens: prevMeta.cached_tokens + usage.meta.cachedTokens,
371|    completion_tokens: prevMeta.completion_tokens + usage.meta.completionTokens,
