1|// Data test: loads the real generated Oz files when present (skips any
2|// missing file) and checks the pipeline invariants hold end to end.
3|import { existsSync, readFileSync } from "node:fs";
4|import { dirname, join } from "node:path";
5|import { fileURLToPath } from "node:url";
6|import { describe, expect, it } from "vitest";
7|import { validateBookCoverage } from "../../core/scenes";
8|import { EMOTIONS } from "../../core/types";
9|
10|const DIR = join(dirname(fileURLToPath(import.meta.url)), "oz");
11|
12|function load(name: string): unknown | null {
13|  const path = join(DIR, name);
14|  if (!existsSync(path)) return null;
15|  return JSON.parse(readFileSync(path, "utf8"));
16|}
17|
18|describe("oz data files", () => {
19|  it("book has 24 chapters and sequential ordinals", () => {
20|    const book = load("book.json") as {
21|      chapters: { ch: number; start_n: number; end_n: number }[];
22|      paragraphs: { n: number }[];
23|      textVersion: string;
24|    } | null;
25|    if (!book) return;
26|    expect(book.chapters.length).toBe(24);
27|    expect(book.paragraphs.map((p, i) => p.n)).toEqual(book.paragraphs.map((_, i) => i + 1));
28|    expect(book.textVersion).toMatch(/^sha256:[0-9a-f]{64}$/);
29|  });
30|
31|  it("scenes cover every paragraph exactly once", () => {
32|    const book = load("book.json") as {
33|      textVersion: string;
34|      chapters: { ch: number; title: string; start_n: number; end_n: number }[];
35|      paragraphs: { id: string; ch: number; n: number; text: string }[];
36|    } | null;
37|    const scenesFile = load("scenes.json") as {
38|      textVersion: string;
39|      scenes: { id: string; ch: number; start_n: number; end_n: number; title: string; summary: string; characters: string[] }[];
40|    } | null;
41|    if (!book || !scenesFile) return;
42|    expect(scenesFile.textVersion).toBe(book.textVersion);
43|    expect(validateBookCoverage(book, scenesFile.scenes)).toEqual([]);
44|  });
45|
46|  it("final vectors sum to 1", () => {
47|    const analysis = load("analysis.json") as {
48|      textVersion: string;
49|      scenes: { id: string; final: { vector: Record<string, number> } | null }[];
50|    } | null;
51|    if (!analysis) return;
52|    for (const scene of analysis.scenes) {
53|      if (!scene.final) continue;
54|      const sum = Object.values(scene.final.vector).reduce((a, b) => a + b, 0);
55|      expect(sum).toBeCloseTo(1, 6);
56|      expect(Object.keys(scene.final.vector).sort()).toEqual([...EMOTIONS].sort());
57|    }
58|  });
